# Initially generated by GitHub Copilot.
import json
import unittest

from author_misc import mam_parsed_docs_build
from mb_author import claim as claim_mod
from verify_mp import payload_examples
from verify_mp import pattern_match
from verify_mp.corpus import Context, Corpus, PlainCorpus


def _make_record(*, claim_id: str, payload, subject: str = "mp:plus"):
    return claim_mod.make_record(
        claim_id,
        payload=payload,
        kind="example",
        subject=subject,
    )


def _ctx(*, plus_files=None, plain_files=None):
    return Context(
        corpus=Corpus(files=[] if plus_files is None else plus_files, book39s=[]),
        corpus_plain=PlainCorpus(files=[] if plain_files is None else plain_files),
        survey={},
        survey_plain={},
    )


class TestVerifyMpPayloadExamples(unittest.TestCase):
    def test_normalize_payload_parses_strict_json_object(self):
        record = _make_record(
            claim_id="mp.plus.example.strict-json",
            payload='  {"k": [1, 2, 3]}  ',
        )

        normalized = payload_examples._normalize_payload(record)

        self.assertEqual(normalized, {"k": [1, 2, 3]})

    def test_normalize_payload_keeps_non_json_string_unchanged(self):
        payload = '"header": {"book24_name": "ספר איוב"}'
        record = _make_record(
            claim_id="mp.plus.example.non-json-fragment",
            payload=payload,
        )

        normalized = payload_examples._normalize_payload(record)

        self.assertEqual(normalized, payload)

    def test_normalize_payload_non_string_passthrough(self):
        payload = {"already": "parsed"}
        record = _make_record(
            claim_id="mp.plus.example.non-string",
            payload=payload,
        )

        normalized = payload_examples._normalize_payload(record)

        self.assertIs(normalized, payload)

    def test_normalize_payload_rejects_legacy_trailing_comma(self):
        record = _make_record(
            claim_id="mp.plus.example.trailing-comma",
            payload='{"a": 1,}',
        )

        with self.assertRaisesRegex(AssertionError, r"payload must be strict JSON"):
            payload_examples._normalize_payload(record)

    def test_match_pattern_marker_name_bare_string_is_literal(self):
        self.assertTrue(
            pattern_match.match_pattern(
                "__verify_mp_any_dict__", "__verify_mp_any_dict__"
            )
        )
        self.assertFalse(pattern_match.match_pattern("__verify_mp_any_dict__", "abc"))

    def test_match_pattern_any_dict_marker(self):
        expected = {pattern_match.ANY_DICT_MARKER_KEY: True}

        self.assertTrue(pattern_match.match_pattern(expected, {"k": "v"}))
        self.assertFalse(pattern_match.match_pattern(expected, ["not", "a", "dict"]))

    def test_match_pattern_any_list_marker(self):
        expected = {pattern_match.ANY_LIST_MARKER_KEY: True}

        self.assertTrue(pattern_match.match_pattern(expected, ["x"]))
        self.assertFalse(pattern_match.match_pattern(expected, {"not": "a list"}))

    def test_match_pattern_any_string_dict_or_list_marker(self):
        expected = {pattern_match.ANY_STRING_DICT_OR_LIST_MARKER_KEY: True}

        self.assertTrue(pattern_match.match_pattern(expected, "abc"))
        self.assertTrue(pattern_match.match_pattern(expected, {"k": "v"}))
        self.assertTrue(pattern_match.match_pattern(expected, ["x", "y"]))
        self.assertFalse(pattern_match.match_pattern(expected, 7))

    def test_match_pattern_wildcard_string_marker(self):
        expected = {pattern_match.WILDCARD_STRING_MARKER_KEY: "והיה מדי ... אמר יהוה"}

        self.assertTrue(
            pattern_match.match_pattern(expected, "והיה מדי שבת בשבתו ... אמר יהוה")
        )
        self.assertFalse(pattern_match.match_pattern(expected, "והיה מדי ... אמר"))

    def test_match_pattern_wildcard_string_non_string_actual(self):
        expected = {pattern_match.WILDCARD_STRING_MARKER_KEY: "prefix ... suffix"}

        self.assertFalse(pattern_match.match_pattern(expected, {"not": "a string"}))
        self.assertFalse(pattern_match.match_pattern(expected, ["not", "a", "string"]))

    def test_match_pattern_wildcard_string_requires_exactly_one_ellipsis(self):
        expected = {
            pattern_match.WILDCARD_STRING_MARKER_KEY: "no wildcard separator here"
        }

        with self.assertRaisesRegex(AssertionError, r"exactly one '\.\.\.'"):
            pattern_match.match_pattern(expected, "anything")

    def test_match_pattern_wildcard_string_requires_string_pattern(self):
        expected = {pattern_match.WILDCARD_STRING_MARKER_KEY: 17}

        with self.assertRaisesRegex(AssertionError, r"value must be a string"):
            pattern_match.match_pattern(expected, "anything")

    def test_match_pattern_wildcard_string_wrapper_must_have_only_one_key(self):
        expected = {
            pattern_match.WILDCARD_STRING_MARKER_KEY: "prefix ... suffix",
            "extra": True,
        }

        with self.assertRaisesRegex(AssertionError, r"must contain only"):
            pattern_match.match_pattern(expected, "prefix x suffix")

    def test_match_pattern_empty_list_is_literal_empty(self):
        self.assertTrue(pattern_match.match_pattern([], []))
        self.assertFalse(pattern_match.match_pattern([], [1]))

    def test_match_pattern_empty_object_is_literal_empty(self):
        self.assertTrue(pattern_match.match_pattern({}, {}))
        self.assertFalse(pattern_match.match_pattern({}, {"x": 1}))

    def test_match_pattern_nonempty_object_requires_exact_keys(self):
        expected = {"a": 1}

        self.assertTrue(pattern_match.match_pattern(expected, {"a": 1}))
        self.assertFalse(pattern_match.match_pattern(expected, {"a": 1, "b": 2}))

    def test_verify_example_payload_searches_recursively(self):
        record = _make_record(
            claim_id="mp.plus.example.recursive",
            payload='{"tmpl_name": "מ:פסוק", "tmpl_params": {"1": "איוב"}}',
            subject="mp:plus",
        )
        ctx = _ctx(
            plus_files=[
                {
                    "book39s": [
                        {
                            "chapters": {
                                "1": {
                                    "1": [
                                        "text",
                                        {
                                            "nested": {
                                                "tmpl_name": "מ:פסוק",
                                                "tmpl_params": {"1": "איוב"},
                                            }
                                        },
                                    ]
                                }
                            }
                        }
                    ]
                }
            ]
        )

        payload_examples.verify_example_payload(record, ctx)

    def test_verify_example_payload_fails_when_not_found(self):
        record = _make_record(
            claim_id="mp.plus.example.not-found",
            payload='{"a": 999}',
            subject="mp:plus",
        )
        ctx = _ctx(plus_files=[{"a": 1}])

        with self.assertRaisesRegex(
            AssertionError, r"example payload pattern not found in corpus"
        ):
            payload_examples.verify_example_payload(record, ctx)

    def test_all_example_json_payload_strings_are_parseable(self):
        claims = mam_parsed_docs_build.collect_explicit_claims()

        failures = []
        for claim_id, record in claims.records_by_id.items():
            if ".example." not in claim_id:
                continue
            if not isinstance(record.payload, str):
                continue
            text = record.payload.strip()
            if not text.startswith("{") and not text.startswith("["):
                continue
            try:
                json.loads(text)
            except json.JSONDecodeError as exc:
                failures.append(f"{claim_id}: {exc}")

        self.assertEqual([], failures, msg="\n".join(failures))

    def test_nested_tmpl_example_uses_narrow_wildcard_token(self):
        claims = mam_parsed_docs_build.collect_explicit_claims()
        record = claims.records_by_id["mp.plus.example.nested-tmpl"]

        self.assertIsInstance(record.payload, str)
        self.assertIn("__verify_mp_any_string_dict_or_list__", record.payload)

    def test_good_ending_examples_are_claims(self):
        claims = mam_parsed_docs_build.collect_explicit_claims()

        self.assertIn(
            "mp.plain.example.good-ending-template-stmpl", claims.records_by_id
        )
        self.assertIn(
            "mp.plus.example.good-ending-template-object", claims.records_by_id
        )
        self.assertIn("mp.plus.example.good-ending-plus-field", claims.records_by_id)


if __name__ == "__main__":
    unittest.main()
